const n=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const h=n.getHours(), m=n.getMinutes(), d=n.getDay();
return {go: (d!==6 && h>=7 && h<=17 && m<15)};

const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1,1]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const filters=tabs.map(t=>({a1Range:"'"+t+"'!A1:Z1500"}));
filters.push({a1Range:"'יעדים'!A2:U200"});
return {tabs: JSON.stringify(tabs), readBody: JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'})};

const MONTHS={'ינואר':1,'פברואר':2,'מרץ':3,'אפריל':4,'מאי':5,'יוני':6,'יולי':7,'אוגוסט':8,'ספטמבר':9,'אוקטובר':10,'נובמבר':11,'דצמבר':12};
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const dkey=s=>{const m=norm(s).match(/(\d{1,2})\s+(\S+)\s+(\d{4})/); if(!m) return 0; const mon=MONTHS[m[2]]; if(!mon) return 0; return (+m[3])*10000+mon*100+(+m[1]);};
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const todayK=nowIL.getFullYear()*10000+(nowIL.getMonth()+1)*100+nowIL.getDate();
const curH=nowIL.getHours();
const startH=s=>{const m=norm(s).match(/(\d{1,2})(?::\d{2})?\s*[-–]/); return m?+m[1]:-1;};
const vr=arr(input.vr).map(v=>(v&&v.valueRange)||v||{}); const tabs=arr(input.tabs).map(norm);
const byName=n=>{ const x=vr.find(v=>{ const r=norm(v.range).replace(/^'/,''); return r.startsWith(n+"'!")||r.startsWith(n+'!'); }); return (x&&x.values)||[]; };
const ALIAS={'אוסי':'אוסי גיאן','אופק פ':'אופק','דוד':'דוד חי','איתמר':'איתמר ששון'};
const deals=[];
tabs.forEach(t=>{
  const rows=byName(t);
  const hN=(rows[0]||[]).map(norm).findIndex(x=>x.startsWith('הערות')); const iN=hN>=0?hN:17;
  rows.forEach((r,i)=>{
    if(i===0||!r) return;
    let rep=norm(r[7]); const name=norm(r[2]); if(!rep||!name) return;
    if(ALIAS[rep]) rep=ALIAS[rep];
    const note=norm(r[iN]);
    if(/בוטל|ביטול|ביטל|לא מעוניין/.test(note)) return;
    const inst=dkey(r[4]); if(inst!==todayK) return;
    if(startH(r[5])!==curH) return;
    deals.push({rep, name, phone:norm(r[3]), slot:norm(r[5])});
  });
});
const targets=byName('יעדים');
const items=[];
for(const r of targets){
  if(!r||norm(r[13])!=='כן') continue;
  let p=digits(r[1]); if(!p) continue;
  if(p.startsWith('0')) p='972'+p.slice(1); else if(!p.startsWith('972')) p='972'+p;
  const full=norm(r[0]); if(!full) continue;
  const first=full.split(' ')[0];
  const mine=deals.filter(d=>d.rep===full);
  if(!mine.length) continue;
  const lines=mine.map(d=>'• '+d.name+' | '+(d.slot||'')+(d.phone?' | '+d.phone:'')).join('\n');
  let msg=first+', עכשיו נפתח חלון ההתקנה אצל:\n'+lines+'\n\nשווה להרים טלפון ללקוח עכשיו ולהזכיר שהטכנאי בדרך 📞';
  if(msg.length>1990) msg=msg.slice(0,1985)+'…';
  items.push({name:first, phone:p, msg});
}
return {items, count:items.length, dealsNow:deals.length};
